use std::sync::{Arc, Mutex, MutexGuard};
use std::collections::HashMap;
use std::fmt;

#[derive(Debug, Clone)]
pub struct AuditEntry {
    pub operation: String,
    pub table: String,
    pub user: String,
    pub timestamp: u64,
}

pub trait AuditSink: Send {
    fn flush(&self, entries: &[AuditEntry]) -> Result<(), DbError>;
}

#[derive(Debug)]
pub enum DbError {
    LockPoisoned,
    WriteConflict,
    AuditFlushFailed(String),
}

impl fmt::Display for DbError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{:?}", self)
    }
}

pub struct ConnectionPool {
    state: Arc<Mutex<PoolState>>,
    audit_buffer: Arc<Mutex<Vec<AuditEntry>>>,
    audit_sink: Arc<dyn AuditSink>,
    flush_threshold: usize,
}

struct PoolState {
    connections: Vec<Connection>,
    active_transactions: HashMap<u64, Transaction>,
    next_tx_id: u64,
}

struct Connection {
    id: u32,
    in_use: bool,
}

struct Transaction {
    conn_id: u32,
    writes: Vec<(String, String)>,
}

impl ConnectionPool {
    pub fn new(pool_size: u32, sink: Arc<dyn AuditSink>, flush_threshold: usize) -> Self {
        let connections = (0..pool_size)
            .map(|id| Connection { id, in_use: false })
            .collect();
        ConnectionPool {
            state: Arc::new(Mutex::new(PoolState {
                connections,
                active_transactions: HashMap::new(),
                next_tx_id: 1,
            })),
            audit_buffer: Arc::new(Mutex::new(Vec::new())),
            audit_sink: sink,
            flush_threshold,
        }
    }

    pub fn begin_transaction(&self, user: &str) -> Result<u64, DbError> {
        let mut state = self.state.lock().map_err(|_| DbError::LockPoisoned)?;
        let conn = state.connections.iter_mut()
            .find(|c| !c.in_use)
            .ok_or(DbError::WriteConflict)?;
        conn.in_use = true;
        let conn_id = conn.id;
        let tx_id = state.next_tx_id;
        state.next_tx_id += 1;
        state.active_transactions.insert(tx_id, Transaction {
            conn_id,
            writes: Vec::new(),
        });
        self.record_audit_holding_state(state, "BEGIN", "*", user)?;
        Ok(tx_id)
    }

    pub fn execute(&self, tx_id: u64, table: &str, value: &str, user: &str) -> Result<(), DbError> {
        let mut state = self.state.lock().map_err(|_| DbError::LockPoisoned)?;
        let tx = state.active_transactions.get_mut(&tx_id)
            .ok_or(DbError::WriteConflict)?;
        tx.writes.push((table.to_string(), value.to_string()));
        self.record_audit_holding_state(state, "WRITE", table, user)?;
        Ok(())
    }

    pub fn commit(&self, tx_id: u64, user: &str) -> Result<(), DbError> {
        let mut state = self.state.lock().map_err(|_| DbError::LockPoisoned)?;
        let tx = state.active_transactions.remove(&tx_id)
            .ok_or(DbError::WriteConflict)?;
        let conn_id = tx.conn_id;
        if let Some(conn) = state.connections.iter_mut().find(|c| c.id == conn_id) {
            conn.in_use = false;
        }
        self.record_audit_holding_state(state, "COMMIT", "*", user)?;
        Ok(())
    }

    /// Records an audit entry. Caller passes the already-acquired MutexGuard for `state`.
    /// If the buffer exceeds threshold, flushes via the audit sink.
    fn record_audit_holding_state(
        &self,
        _state_guard: MutexGuard<'_, PoolState>,
        operation: &str,
        table: &str,
        user: &str,
    ) -> Result<(), DbError> {
        let entry = AuditEntry {
            operation: operation.to_string(),
            table: table.to_string(),
            user: user.to_string(),
            timestamp: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_secs(),
        };
        let mut buffer = self.audit_buffer.lock().map_err(|_| DbError::LockPoisoned)?;
        buffer.push(entry);
        if buffer.len() >= self.flush_threshold {
            let entries: Vec<AuditEntry> = buffer.drain(..).collect();
            // Drop buffer lock before calling sink to avoid holding two locks
            drop(buffer);
            // NOTE: _state_guard is still held here during the flush callback
            self.audit_sink.flush(&entries).map_err(|e| {
                DbError::AuditFlushFailed(format!("{}", e))
            })?;
        }
        Ok(())
    }
}

/// Example audit sink that writes back to the same pool (e.g., audit table)
pub struct SelfLoggingAuditSink {
    pool: Option<Arc<ConnectionPool>>,
}

impl SelfLoggingAuditSink {
    pub fn new() -> Self {
        SelfLoggingAuditSink { pool: None }
    }
    pub fn set_pool(&mut self, pool: Arc<ConnectionPool>) {
        self.pool = Some(pool);
    }
}

impl AuditSink for Mutex<SelfLoggingAuditSink> {
    fn flush(&self, entries: &[AuditEntry]) -> Result<(), DbError> {
        let inner = self.lock().map_err(|_| DbError::LockPoisoned)?;
        if let Some(ref pool) = inner.pool {
            // This attempts to acquire pool.state lock, which is already held
            // by the caller -> DEADLOCK (reentrancy on non-reentrant Mutex)
            let tx_id = pool.begin_transaction("audit_system")?;
            for entry in entries {
                pool.execute(tx_id, "audit_log", &entry.operation, "audit_system")?;
            }
            pool.commit(tx_id, "audit_system")?;
        }
        Ok(())
    }
}
